INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(106428, 'ruRU', '', 'Терпение, брат. Увидеть Когтекрыла воочию — зрелище, которое запомнится. Смотри! Наш друг возвращается!', 24330),
(106460, 'ruRU', '', 'Спасибо, что вернул нам те бутылки!', 24330),
(106465, 'ruRU', '', 'Мудрые слова, житель низин.', 24330),
(106467, 'ruRU', '', 'Мне сказали, твой отец тоже был убит. Ты отомстил за него?', 24330),
(106468, 'ruRU', '', 'В моём случае спасение моего народа также означает месть за отца.', 24330),
(106472, 'ruRU', '', 'Это говорит твой опыт общения с новыми вождями, житель низин?', 24330),
(106473, 'ruRU', '', 'Хална объединил племена ещё до того, как нашёл молот? Как?', 24330),
(106490, 'ruRU', '', '$ct, что за странное сооружение под тобой! Теперь я могу отправлять тебя прямо в Высокогорье из Небесной Твердыни, когда пожелаешь!', 24330),
(106494, 'ruRU', '', 'Силы Седогрива удерживают эту башню Стража. Сломите их ряды! Не щадите никого!', 24330),
(106495, 'ruRU', '', 'Решающая победа! Эти комнатные пёсики Альянса разбегаются перед мощью Орды!', 24330),
(106502, 'ruRU', '', 'Нельзя позволить Осквернённым Скверной процветать на нашем острове. Ты знаешь, что делать.', 24330),
(106503, 'ruRU', '', 'Отлично сделано, $n. Теперь, когда Осквернённые ослаблены, мы на шаг ближе к тому, чтобы разобраться с этим бардаком.', 24330),
(106505, 'ruRU', '', '<Этап 1 завершён>', 24330),
(106506, 'ruRU', '', '<Этап 2 завершён>', 24330),
(106633, 'ruRU', '', 'Чумные поветрия Легиона уничтожат ваш хрупкий город!', 24330),
(106658, 'ruRU', '', 'Ваш город обречён!', 24330),
(106725, 'ruRU', '', 'Сначала наш форпост захлестнули медведи, а теперь браконьеры крадут медвежьи шкуры! Куда уж хуже?', 24330),
(106726, 'ruRU', '', 'Благодаря твоей помощи мы, возможно, сможем отбить этот форпост!', 24330),
(106727, 'ruRU', '', 'Эти медведи выгнали нас из нашего поселения и уничтожают наши запасы. Прогони их и посмотри, не сможешь ли вернуть немного нашего зерна, пока будешь там.', 24330),
(106729, 'ruRU', '', 'Эти медведи такие необузданные! Спасибо!', 24330),
(106730, 'ruRU', '', 'Эти медведи такие необузданные! Спасибо!', 24330),
(106732, 'ruRU', '', 'Должно быть, гарпии прокляли этих бедных медведей. Как ужасно! Прошу, избавь их от страданий.', 24330),
(106734, 'ruRU', '', 'Даже шкуры теперь непригодны. Гарпии за это заплатят!', 24330),
(106736, 'ruRU', '', '|TInterface\\Icons\\inv_misc_herb_stormvine:20|t%s начинает издавать |cFFFF0000|Hspell:192985|h[Крик гнева]|h|r!', 24330),
(106737, 'ruRU', '', '|TInterface\\Icons\\inv_misc_herb_stormvine:20|t%s начинает издавать |cFFFF0000|Hspell:192985|h[Крик гнева]|h|r!', 24330),
(106738, 'ruRU', '', 'Дрогбары раскопали древнее знание времён Смертокрыла. Я слышу, как духи кричат от боли. Прошу, останови их!', 24330),
(106739, 'ruRU', '', 'Эта тёмная руда, этот... элементий — оружие, которым, я надеюсь, дрогбары никогда не овладеют в совершенстве.', 24330),
(106756, 'ruRU', '', 'Эммарел Хранительница Тени — благородная душа. Тавры Высокогорья издавна были союзниками Незримого Пути.$b$bКогтекрыл, копьё, которым владел мой предок Хална Высокогорье, было утрачено в битве с свирепой ночной саблей по имени Дакарр. Многие пытались вернуть его... и все потерпели неудачу.$b$bНаши старейшины верят, что возвращение Когтекрыла — ключ к изгнанию Легиона с наших земель.$b$bМы с братом Вухо отправляемся убить зверя и забрать копьё. Если бы ты присоединился к нам, успех был бы гарантирован!', 24330),
(106761, 'ruRU', '', 'Довольно!', 24330),
(106795, 'ruRU', '', 'Вам никогда не остановить нас. Яндвик падёт!', 24330),
(106796, 'ruRU', '', 'Эй, привет, друг! Мы ищем "ассистента", который поможет нам протестировать кое-какое из этого оружия. Интересно?', 24330),
(106797, 'ruRU', '', 'О, отлично, прототип вернулся целым. И, эм, ты тоже выжил!', 24330),
(106799, 'ruRU', '', 'Привет, $ct!', 24330),
(106800, 'ruRU', '', 'В лесу всё просто чудесно, $ct.', 24330),
(106801, 'ruRU', '', 'Доброго дня тебе, $ct.', 24330),
(106806, 'ruRU', '', 'Милуна решительно выпячивает грудь, шмыгая носом.', 24330),
(106807, 'ruRU', '', 'Мы справимся, $n. Джаханир рассчитывает на нас!', 24330),
(106808, 'ruRU', '', 'Я заберу эту башню вместе с головами гилнеасцев, что её удерживают! В атаку!', 24330),
(106809, 'ruRU', '', 'Ох, чёрт возьми! Я не знаю, что делать!', 24330),
(106810, 'ruRU', '', 'Наши силы побеждают! Смотрите, как они паникуют и бегут, точно псы! За Орду!', 24330);
